package com.anssa8bu.ssafy.common.redis; import org.springframework.boot.context.properties.ConfigurationProperties; import java.time.*;
@ConfigurationProperties("app.redis.ttl") public record RedisTtlProperties(Duration session,Duration trainingLease,Duration purgeLease,Duration trainingProfile,Duration devicePresence,Duration sseEvent,Duration idempotency,Duration rateLimit){public RedisTtlProperties{session=positive(session,"session");trainingLease=positive(trainingLease,"trainingLease");purgeLease=positive(purgeLease,"purgeLease");trainingProfile=positive(trainingProfile,"trainingProfile");devicePresence=positive(devicePresence,"devicePresence");sseEvent=positive(sseEvent,"sseEvent");idempotency=positive(idempotency,"idempotency");rateLimit=positive(rateLimit,"rateLimit");} private static Duration positive(Duration d,String n){if(d==null||d.isZero()||d.isNegative())throw new IllegalArgumentException(n+" TTL must be positive");return d;} public Duration sessionUntil(Instant expiresAt,Clock clock){Duration d=Duration.between(clock.instant(),expiresAt);if(d.isZero()||d.isNegative())throw new IllegalArgumentException("session already expired");return d.compareTo(session)>0?session:d;}}
